from itertools import permutations
# each option: (equal sides known, equal perimeter known, extra info)
data = {"A": (1, False), "B": (2, False), "C": (1, False), "D": (1, False)}
data["B"] = (2, True)
def sufficient(sides, perim):
    if sides == 2 and perim:
        sides = 3          # third side = P - a - b
    return sides == 3      # SSS (no option gives an included angle plus two sides)
# counterexample for C/D: base 4, height 3, apex at x=1 vs x=2 -> same area, different sides
t1 = sorted([4, (1**2 + 9) ** 0.5, (3**2 + 9) ** 0.5]); t2 = sorted([4, (2**2 + 9) ** 0.5, (2**2 + 9) ** 0.5])
assert t1 != t2
opts = {k: sufficient(*v) for k, v in data.items()}
result = True
match = [k for k, v in opts.items() if v == result]
assert len(match) == 1
print(f"ANSWER={match[0]}")

