opts = {"A": "A + K / J - P = D", "B": "K + A / P - D % J", "C": "J % P = K + A = D", "D": "D + K = A / P - J"}
def facts(expr):
    t = expr.split()
    parent, female, male = set(), set(), set()
    for x, op, y in zip(t[0::2], t[1::2], t[2::2]):
        if op == "+": parent.add((x, y)); female.add(x)
        elif op == "-": parent.add((x, y)); male.add(x)
        elif op == "$": parent.add((y, x)); male.add(x)
        elif op == "%": female.add(x)
        elif op == "/": female.add(x); male.add(y)
        elif op == "=": male.add(x)
    return parent, female, male
def daughter(expr, a="A", k="K"):
    parent, female, male = facts(expr)
    return (k, a) in parent and a in female and a not in male
match = [k for k, v in opts.items() if daughter(v)]
assert len(match) == 1
print(f"ANSWER={match[0]}")
